export function manifest_charge(adult_count, youth_count, vehicle_count, peak_departure) {
  const travellers = adult_count + youth_count;
  const passengerCharge = adult_count * 1100 + youth_count * 650;
  const vehicleCharge = vehicle_count * 2400;
  const peakCharge = peak_departure ? travellers * 125 + vehicle_count * 350 : 0;
  return passengerCharge + vehicleCharge + peakCharge;
}

