from pydantic import BaseModel, ConfigDict, Field


class RequestInput(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)

    adult_count: int = Field(ge=0)
    youth_count: int = Field(ge=0)
    vehicle_count: int = Field(ge=0)
    peak_departure: bool


def traveller_total(adults: int, youths: int) -> int:
    return adults + youths


def passenger_charge(adults: int, youths: int) -> int:
    return adults * 1100 + youths * 650


def vehicle_charge(vehicles: int) -> int:
    return vehicles * 2400


def peak_charge(adults: int, youths: int, vehicles: int, peak: bool) -> int:
    if not peak:
        return 0
    return traveller_total(adults, youths) * 125 + vehicles * 350


def manifest_charge(adults: int, youths: int, vehicles: int, peak: bool) -> int:
    return (
        passenger_charge(adults, youths)
        + vehicle_charge(vehicles)
        + peak_charge(adults, youths, vehicles, peak)
    )


def handle(value: RequestInput) -> dict[str, object]:
    travellers = traveller_total(value.adult_count, value.youth_count)
    vehicle = vehicle_charge(value.vehicle_count)
    mode = "mixed" if value.vehicle_count > 0 and travellers > 0 else "vehicle" if value.vehicle_count > 0 else "foot"
    return {"traveller_total": travellers, "passenger_charge_cents": passenger_charge(value.adult_count, value.youth_count), "vehicle_charge_cents": vehicle, "peak_charge_cents": peak_charge(value.adult_count, value.youth_count, value.vehicle_count, value.peak_departure), "manifest_charge_cents": manifest_charge(value.adult_count, value.youth_count, value.vehicle_count, value.peak_departure), "boarding_load": travellers + value.vehicle_count * 3, "travel_mode": mode}

