const requiredCooling = (measured, target, drift, doorOpen) => {
  const corrected = measured + (doorOpen ? 2 : 0);
  const excessHeat = Math.max(corrected - target - drift, 0);
  return BigInt(Math.ceil(excessHeat / 3));
};
export async function loadParley() { return { required_cooling: requiredCooling }; }

