const manifestCharge = (adultCount, youthCount, vehicleCount, peakDeparture) => {
  const travellerTotal = adultCount + youthCount;
  const passengerCharge = adultCount * 1100 + youthCount * 650;
  const vehicleCharge = vehicleCount * 2400;
  const peakCharge = peakDeparture
