export type RequestInput={measured_degrees:number;target_degrees:number;allowed_drift:number;door_open:boolean};
export const correctedDegrees=(m:number,d:boolean)=>m+(d?2:0);
export const requiredCooling=(m:number,t:number,a:number,d:boolean)=>Math.trunc((Math.max(correctedDegrees(m,d)-t-a,0)+2)/3);
