use serde::{Deserialize,Serialize};
#[derive(Deserialize)] #[serde(deny_unknown_fields)] pub struct RequestInput{pub document_count:i64,pub pages_each:i64,pub requested_years:i64,pub legal_hold:bool}
impl RequestInput{pub fn valid(&self)->bool{self.document_count>=0&&self.pages_each>=0&&self.requested_years>=0}}
#[derive(Serialize)] pub struct ResponseOutput{pub page_total:i64,pub base_months:i64,pub retained_months:i64,pub review_batches:i64,pub retention_score:i64,pub retention_class:String}
pub fn retention_index(d:i64,p:i64,y:i64,h:bool)->i64{let total=d*p;let base=y*12;let retained=if h{base.max(84)}else{base};let batches=total/200+i64::from(total%200!=0);retained+batches*3}
pub fn handle(x:RequestInput)->ResponseOutput{let total=x.document_count*x.pages_each;let base=x.requested_years*12;let retained=if x.legal_hold{base.max(84)}else{base};let batches=total/200+i64::from(total%200!=0);ResponseOutput{page_total:total,base_months:base,retained_months:retained,review_batches:batches,retention_score:retention_index(x.document_count,x.pages_each,x.requested_years,x.legal_hold),retention_class:if x.legal_hold{"held".into()}else{"standard".into()}}}
#[unsafe(no_mangle)] pub extern "C" fn parley_retention_index(d:i64,p:i64,y:i64,h:i32)->i64{retention_index(d,p,y,h!=0)}

