export type RequestInput = { adult_count: number; youth_count: number; vehicle_count: number; peak_departure: boolean };
export const manifestCharge = (adultCount: number, youthCount: number, vehicleCount: number, peakDeparture: boolean) => {
  const travellerTotal = adultCount + youthCount;
  const passengerCharge = adultCount * 1100 + youthCount * 650;
  const vehicleCharge = vehicleCount * 2400;
  const peakCharge = peakDeparture ? travellerTotal * 125 + vehicleCount * 350 : 0;
  return passengerCharge + vehicleCharge + peakCharge;
};
