const retentionIndex = (documentCount, pagesEach, requestedYears, legalHold) => {
  const documents = BigInt(documentCount);
  const pages = BigInt(pagesEach);
  const years = BigInt(requestedYears);
  const total = documents * pages;
  const base = years * 12n;
  const retained = legalHold ? (base > 84n ? base : 84n) : base;
  const batches = (total + 199n) / 200n;
  return retained + batches * 3n;
};
export async function loadParley() { return { retention_index: retentionIndex }; }

