export type RequestInput={document_count:number;pages_each:number;requested_years:number;legal_hold:boolean};
export const retentionIndex=(documentCount:number,pagesEach:number,requestedYears:number,legalHold:boolean)=>{
  const pageTotal=documentCount*pagesEach;
  const baseMonths=requestedYears*12;
  const retainedMonths=legalHold?Math.max(baseMonths,84):baseMonths;
  const reviewBatches=pageTotal===0?0:Math.ceil(pageTotal/200);
  return retainedMonths+reviewBatches*3;
};
export const handle=(v:RequestInput)=>{const total=v.document_count*v.pages_each;const base=v.requested_years*12;const retained=v.legal_hold?Math.max(base,84):base;const batches=total===0?0:Math.ceil(total/200);return {page_total:total,base_months:base,retained_months:retained,review_batches:batches,retention_score:retentionIndex(v.document_count,v.pages_each,v.requested_years,v.legal_hold),retention_class:v.legal_hold?"held":"standard"};};
export async function loadParley(){return {retention_index:(d:number,p:number,y:number,h:boolean)=>BigInt(retentionIndex(d,p,y,h))};}

