pub fn manifest_charge(a:i64,y:i64,v:i64,p:bool)->i64{
    let travellers=a+y;
    let passenger=a*1100+y*650;
    let vehicle=v*2400;
    let peak=if p{travellers*125+v*350}else{0};
    passenger+vehicle+peak
}
