const maxBodyBytes = 16_384;
const schema = z.object({ purchase_count:z.number().int().nonnegative(), stamps_each:z.number().int().nonnegative(), claimed_stamps:z.number().int().nonnegative(), double_day:z.boolean() }).strict();
const response = (value: unknown, status = 200) => new Response(JSON.stringify(value), { status, headers: { "content-type": "application/json" } });
const error = (code: string, status: number, detail: string) => response({ error: code, detail }, status);
const app = new Hono();

app.get("/health/live", () => response({ service: "Loyalty Stamps", ready: true }));
