import { z } from "zod";
import { handle } from "./logic.js";

declare const process: { env: Record<string, string | undefined> };
const maxBodyBytes = 16_384;
const schema = z.object({ measured_degrees:z.number().int().nonnegative(), target_degrees:z.number().int().nonnegative(), allowed_drift:z.number().int().nonnegative(), door_open:z.boolean() }).strict();
const response = (value: unknown, status = 200) => new Response(JSON.stringify(value), { status, headers: { "content-type": "application/json" } });
const error = (code: string, status: number, detail: string) => response({ error: code, detail }, status);
const app = new Hono();

app.get("/health/live", () => response({ service: "Cold Storage", ready: true }));
