use serde::{Deserialize,Serialize};
#[derive(Deserialize)] #[serde(deny_unknown_fields)] pub struct RequestInput{pub purchase_count:i64,pub stamps_each:i64,pub claimed_stamps:i64,pub double_day:bool}
impl RequestInput{pub fn valid(&self)->bool{self.purchase_count>=0&&self.stamps_each>=0&&self.claimed_stamps>=0}}
#[derive(Serialize)] pub struct ResponseOutput{pub base_stamps:i64,pub bonus_stamps:i64,pub spendable_stamps:i64,pub reward_count:i64,pub leftover_stamps:i64,pub reward_stage:String}
pub fn claimable_rewards(p:i64,e:i64,c:i64,d:bool)->i64{let spendable=(p*e+if d{p}else{0}-c).max(0);spendable/10}
pub fn handle(x:RequestInput)->ResponseOutput{let base=x.purchase_count*x.stamps_each;let bonus=if x.double_day{x.purchase_count}else{0};let spendable=(base+bonus-x.claimed_stamps).max(0);let rewards=claimable_rewards(x.purchase_count,x.stamps_each,x.claimed_stamps,x.double_day);ResponseOutput{base_stamps:base,bonus_stamps:bonus,spendable_stamps:spendable,reward_count:rewards,leftover_stamps:spendable%10,reward_stage:if rewards>0{"ready".into()}else{"collecting".into()}}}
#[unsafe(no_mangle)] pub extern "C" fn parley_claimable_rewards(p:i64,e:i64,c:i64,d:i32)->i64{claimable_rewards(p,e,c,d!=0)}

